if __name__ == '__main__':
    import re
    bad = 0
    def chk(name, s, lo, hi):
        global bad
        items = [i.strip() for i in s.split(';')]
        if not (lo <= len(items) <= hi):
            print('COUNT', name, len(items)); bad += 1
        for i in items:
            if not i or re.search(r'[{}|]|: ', i):
                print('BAD ITEM', name, repr(i)); bad += 1
    for k, v in FORMS.items():
        assert len(v) == 8, k
        for n, s in zip('subjects materials techniques finishes colours scales wear'.split(), v[1:]):
            chk(k + '.' + n, s, 8, 10)
        print(k, v[0], [len(x.split(';')) for x in v[1:]])
    for k, s in SHARED.items():
        chk(k, s, 10, 12)
    assert set(DISPLAY) == set(FORMS)
    for k, v in DISPLAY.items():
        chk('display.' + k, v, 6, 8)
    print(len(FORMS), 'forms', 'bad', bad)
